public static GUPPriceEngineMarginCodeLineFilter getInstance()
{
    return new GUPPriceEngineMarginCodeLineFilter();
}

    /// <summary>
    /// Filter margin components by salesLine's currenty and unit. 
    /// </summary>
    /// <param name = "_salesTable">Sales Table.</param>
    /// <param name = "_salesLine">Sales Line.</param>
    /// <param name = "_allMarginCodeLineList">All margin code lines, sorted by setup's computing sequence.</param>
    /// <param name = "_lineRecIdSet">All lines passed the filter.</param>
    /// <param name = "_priorityCache">Priority used in sort.</param>
    /// <returns>A list of GUPPriceEngineMarginComponent, sorted by the computation sequence.</returns>
    public List filterMarginCodeLineList(SalesTable _salesTable,
        SalesLine _salesLine,
        List _allMarginCodeLineList,
        Set _lineRecIdSet,
        GUPPriceEngineAttributeGroupPriorityCache _priorityCache)
    {
        InventDim inventDim = _salesLine.inventDim();
        SalesPurchLineInterface salesPurchLineInterface = _salesLine.salesPurchLineInterface();
        
        // List<GUPPriceEngineMarginComponent> -- returned list.
        List marginComponentList = new List(Types::AnyType);
        str currentComponentCodeName = "";
        GUPPriceMarginComponentSetup currentComponentSetup;

        ListEnumerator listEnumerator = _allMarginCodeLineList.getEnumerator();

        // Key = GUPPriceEngineAbstractLine.parmAttributeGroupKey().
        // Value = GUPPriceEngineMarginCodeLineAggregation.
        Map aggregationTempMap = new Map(Types::String, Types::AnyType);

        while (listEnumerator.moveNext())
        {
            GUPPriceEngineMarginCodeLine line = listEnumerator.current();
            
            // When new setup line is found, compose current margin component, then switch to next.
            if (currentComponentCodeName == "" || line.parmComponentSetup().PriceComponentCodeName != currentComponentCodeName)
            {
                if (currentComponentCodeName != "")
                {
                    this.composeMarginComponent(marginComponentList, currentComponentSetup, aggregationTempMap);
                }

                aggregationTempMap = new Map(Types::String, Types::AnyType);
                currentComponentSetup = line.parmComponentSetup();
                currentComponentCodeName = currentComponentSetup.PriceComponentCodeName;
            }

            // Unit and currency (and other fixed) filters.
            if (!this.priceAdjustmentValid(line, _salesTable, _salesLine))
            {
                continue;
            }

            // Record 'in-used' price adjustment lines.
            _lineRecIdSet.add(line.parmJournalLineRecId());

            // Stores competing lines in same aggregation object.
            str attributeGroupKey = line.parmAttributeGroupKey();
            GUPPriceEngineMarginCodeLineAggregation aggregation = null;
            if (aggregationTempMap.exists(attributeGroupKey))
            {
                GUPPriceEngineMarginCodeLineAggregation competeAggregation = aggregationTempMap.lookup(attributeGroupKey);

                // Extra check to prevent hash collision.
                if (competeAggregation.canAddAsCompeteLine(line))
                {
                    aggregation = competeAggregation;
                }
            }
            
            if (aggregation == null)
            {
                aggregation = new GUPPriceEngineMarginCodeLineAggregation();
                aggregationTempMap.add(attributeGroupKey, aggregation);
            }

            aggregation.addCompeteLine(line,
                _priorityCache.getLinePriority(line, currentComponentCodeName));
        }

        // Last margin component.
        this.composeMarginComponent(marginComponentList, currentComponentSetup, aggregationTempMap);

        return marginComponentList;
    }

    private boolean priceAdjustmentValid (GUPPriceEngineMarginCodeLine _line,
        SalesTable _salesTable,
        SalesLine _salesLine)
    {
        if (!this.doesCurrencyCodeQualify(_line, _salesLine.CurrencyCode)
            || !this.doesUnitIdQualify(_line, _salesLine.SalesUnit)
            || !this.isIncludedByTradeAgreement(_line, _salesTable, _salesLine))
        {
            return false;
        }

        return true;
    }

/// <summary>
/// Filter by unit Id.
/// </summary>
/// <param name = "_line">A pricingRule line.</param>
/// <param name = "_unitSymbol">The line's unit must matches salesLine's salesUnit, or it is marked as 'apply to all'.</param>
/// <returns>True of unit id qualifies.</returns>
private boolean doesUnitIdQualify(GUPPriceEngineMarginCodeLine _line,
    str _unitSymbol)
{
    return _line.parmComponentLine().UnitAppliesToAll ||
        _line.parmUnitSymbol() == _unitSymbol;
}

    private void composeMarginComponent(List _marginComponentList, 
        GUPPriceMarginComponentSetup _currentComponentSetup,
        Map _aggregationTempMap)
    {
        // List<GUPPriceEngineMarginCodeLineAggregation>.
        List percentageAggregationList = new List(Types::AnyType);
        List fixedAmountAggregationList = new List(Types::AnyType);

        MapEnumerator mapEnumerator = _aggregationTempMap.getEnumerator();
        while (mapEnumerator.moveNext())
        {
            GUPPriceEngineMarginCodeLineAggregation aggregation = mapEnumerator.currentValue();

            // Sort competing lines by attribute priority descending, then by adjustment value aescending.
            aggregation.sortLineList();

            if (aggregation.parmPercentListLength() > 0)
            {
                percentageAggregationList.addEnd(aggregation);
            }

            if (aggregation.parmFixedAmountListLength() > 0)
            {
                fixedAmountAggregationList.addEnd(aggregation);
            }
        }

        // Sorting is done during object creation.
        GUPPriceEngineMarginComponent marginComponent = new GUPPriceEngineMarginComponent(
            _currentComponentSetup,
            percentageAggregationList.empty() ? null : percentageAggregationList,
            fixedAmountAggregationList.empty() ? null : fixedAmountAggregationList);
    
        _marginComponentList.addEnd(marginComponent);
    }
